return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-09-08T21:12:46+00:00','po-revision-date'=>'2026-09-08T21:12:46+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'Premješta medijsku biblioteku ove web-lokacije u Zinn® objektnu pohranu i poslužuje je s CDN-a. Konfigurira se s vaše Zinn® upravljačke ploče — u WordPress se nikada ne upisuje pristupni ključ.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Spremljeno. Unesite novu vrijednost da biste je zamijenili.','Filter this list…'=>'Filtriraj ovaj popis…','Filter this list'=>'Filtriraj ovaj popis','Nothing matches that filter.'=>'Ništa ne odgovara tom filteru.','Add a row'=>'Dodaj redak','Remove this row'=>'Ukloni ovaj red','Remove'=>'Ukloni','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — pregled','Overview'=>'Pregled','Every Zinn® plugin on this site, and whether it is working.'=>'Svaki Zinn® dodatak na ovoj stranici i radi li on.','No connection is needed for this plugin.'=>'Za ovaj dodatak nije potrebna nikakva veza.','Open settings'=>'Otvori postavke','You do not have permission to change these settings.'=>'Nemate dopuštenje za promjenu ovih postavki.','Settings sections'=>'Odjeljci postavki','Support'=>'Podrška','Save changes'=>'Spremi promjene','Tools'=>'Alati','Export settings'=>'Izvoz postavki','Reset to defaults'=>'Vrati na zadano','This puts every setting on this plugin back to its default. Continue?'=>'Ovo vraća svaku postavku ovog dodatka na zadane vrijednosti. Nastaviti?','Diagnostics for support'=>'Dijagnostika za podršku','Import a settings file'=>'Uvezi datoteku s postavkama','Import'=>'Uvezi','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Izvezene datoteke nikada ne sadrže lozinke, tokene ili API ključeve – morat ćete ih ponovno unijeti na novoj web-lokaciji.','Settings saved.'=>'Postavke su spremljene.','Every setting on this plugin is back to its default.'=>'Svaka postavka na ovom dodacima vraćena je na zadane vrijednosti.','Done.'=>'Gotovo.','That action is not available.'=>'Ta radnja nije dostupna.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Datoteku nije bilo moguće pročitati. Odaberite datoteku postavki izvezenu iz Zinn® dodatka.','That file is too large to be a settings export.'=>'Ta je datoteka prevelika da bi bila izvoz postavki.','That file is not a Zinn® settings export.'=>'Ta datoteka nije izvoz Zinn® postavki.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Ta je datoteka izvezena iz drugog dodatka (%s), pa bi njen uvoz ovdje pohranio postavke koje ovaj dodatak ne razumije.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d postavka je uvezena. Zaporke i API ključevi nikada se ne nalaze u izvozu, stoga ih unesite ponovno.' . "\0" . 'Uvezeno je %d postavki. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih unesite ponovno.' . "\0" . 'Uvezeno je %d postavki. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih unesite ponovno.','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® nije vratio token. Na ovoj stranici ništa nije promijenjeno.','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'Ova stranica više nije povezana s prijenosom medija na Zinn®. Novi prijenos ostat će na ovom poslužitelju. Ponovno ju povežite sa svoje nadzorne ploče za Zinn Digital®.','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® je odgovorio s HTTP %d.','Disconnected by Zinn Digital®.'=>'Prekinuta veza od strane Zinn Digital®-a.','Connected'=>'Povezano','Connecting…'=>'Povezivanje…','Connected, but something needs attention'=>'Povezano, ali nešto zahtijeva pažnju','Not connected'=>'Nije povezano','Running on your own account'=>'Radi na vašem računu','We could not check this'=>'Nismo mogli provjeriti ovo','This plugin did not say why. Send a diagnostics report and we will look.'=>'Ovaj dodatak nije naveo razlog. Pošaljite dijagnostičko izvješće i mi ćemo ga pregledati.','Connection status'=>'Status veze','Last checked %s ago.'=>'Zadnji put provjereno prije %s.','(opens in a new tab)'=>'(otvara se u novoj kartici)','Send this to Zinn® support'=>'Pošaljite ovo Zinn® podršci','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'To je točno ono što će biti poslano — ništa drugo i ništa skriveno. Vaše lozinke, tokeni i API ključevi nisu uključeni u to.','The diagnostics report that will be sent'=>'Dijagnostičko izvješće koje će biti poslano','Copy to clipboard'=>'Kopiraj u međuspremnik','Send this report to Zinn® support'=>'Pošaljite ovo izvješće Zinn® podršci','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otvaramo vam zahtjev za podršku i odgovaramo e-poštom. Ako ga radije ne biste poslali, kopirajte ga iznad i sami ga zalijepite u zahtjev.','Copied'=>'Kopirano','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Nismo mogli kontaktirati Zinn Digital® s ovog poslužitelja (%s). Umjesto toga kopirajte gore navedeno izvješće i otvorite zahtjev — s vašim postavkama nije ništa u redu.','Sent. Zinn® support has your report and will reply by email.'=>'Podrška za Zinn® primila je vaše izvješće i odgovorit će vam putem e-pošte.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Podrška za Zinn® primila je vaše izvješće — referenca %s — i odgovorit će vam putem e-pošte.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Poslali ste nekoliko izvješća u kratkom vremenu. Pričekajte nekoliko minuta i pokušajte ponovno – ona prethodna su stigla.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® trenutno nije mogao prihvatiti izvješće — problem je s naše strane, ne s vaše. Pokušajte ponovno uskoro ili kopirajte gornje izvješće u tiket.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Izvještaj je odbijen (HTTP %d). Kopirajte ga gore i otvorite zahtjev navodeći taj broj.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički priručnici','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne sigurnosne kopije, besplatna migracija i upravljačka ploča prilagođena korisnicima koji vode više web-mjesta.','The Zinn® marketplace'=>'Zinn® tržnica','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajte već uspostavljene stranice, domene i postavljanja poveznica, uz sigurno čuvanje novca dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite stručnjake koji se time bave','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih zanimanja: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i dopustite im da daju ponude.','Media Offload'=>'Izmještanje medija','Connection'=>'Veza','What gets moved'=>'Što se premješta','How media is served'=>'Kako se poslužuju medijski sadržaji','Move a batch now'=>'Premjesti grupu odmah','Media already moved is never affected by a change here — its address does not change.'=>'Mediji koji su već premješteni nikada nisu pogođeni promjenom ovdje — njihova adresa se ne mijenja.','New uploads'=>'Nova otpremanja','Move new uploads to Zinn® storage as they arrive'=>'Premjestite nova preuzimanja u Zinn® pohranu čim stignu','Existing media'=>'Postojeći mediji','Keep moving the media library that is already here'=>'Nastavite pomicati medijsku biblioteku koja je već ovdje','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'Nekoliko datoteka na sat, u pozadini, nastavljajući tamo gdje je stalo. Isključivanje ovoga pauzira proces; ništa što je već premješteno neće se vratiti.','Files per hourly pass'=>'Datoteka po satu','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'Svaki privitak sastoji se od nekoliko datoteka i svaka je potpuno prenesena. Povećajte ovu vrijednost na brzom poslužitelju s velikim ograničenjem izvršavanja; smanjite je ako se obrade prekidaju prerano.','Leave files smaller than'=>'Ostavite datoteke manje od','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'Kilobajti. Mala ikona košta više u dodatnoj vezi nego što štedi na disku, tako da rijetko postoji razlog za premještanje jedne. Postavite na 0 za premještanje svega.','Never move these types'=>'Nikada ne premještaj ove vrste','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'Korisno kada dodatak čita datoteku izravno s diska — font, PDF koji generator obrazaca ispunjava, audio datoteku unutar koje se reproduktor kreće.','These two are the ones to be careful with — read each description before changing it.'=>'Na ova dva treba pripaziti – pročitajte svaki opis prije nego što ga promijenite.','Serve from Zinn® storage'=>'Poslužite iz Zinn® pohrane','Point image and file addresses at Zinn® storage'=>'Usmjerite adrese slika i datoteka na Zinn® pohranu','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'Isključeno, datoteke su učitane, ali se i dalje poslužuju s ovog poslužitelja — što je sigurno stanje dok provjeravate je li sve stiglo. Uključeno, posjetiteljima se sadržaj poslužuje iz pohrane i ovaj poslužitelj prestaje preuzimati promet.','Free the disk space'=>'Oslobodi prostor na disku','Delete the local copy once every size has uploaded'=>'Izbriši lokalnu kopiju nakon što se svaka veličina prenese','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'Ovo je točka prebacivanja, a ujedno je i nepovratna polovica. Ostavite je isključenom dok se opcija „Serve from Zinn® storage” ne uključi i dok ne provjerite svoju web-lokaciju – lokalna kopija jedino je što vas spašava ako je nešto propušteno.','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'Brisanje lokalnih kopija ne može se poništiti s ovog zaslona. Prvo napravite sigurnosnu kopiju — dodatak Zinn® Connector može to učiniti umjesto vas.','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'Ova stranica još uvijek nije povezana sa Zinn® pohranom, tako da nema mjesta na koje bi se preselili medijski sadržaji.','%d attachment moved.'=>'%d privitak premješten.' . "\0" . '%d privitaka premješteno.' . "\0" . '%d privitaka premješteno.','This site is not connected to Zinn® storage.'=>'Ova web-lokacija nije povezana sa Zinn® pohranom.','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'Ništa nije u kvaru – medijski sadržaj jednostavno još nije uparen. Mediji ostaju na ovom poslužitelju dok se to ne učini.','Connected, but the last upload failed.'=>'Povezano, ali zadnji prijenos nije uspio.','Try a batch now'=>'Isprobajte skupnu obradu sada','Connected. Every attachment has been moved.'=>'Povezano. Svaki privitak je premješten.','Connected. %1$s of %2$s attachments still on this server.'=>'Povezano. Još uvijek je %1$s od %2$s privitaka na ovom poslužitelju.','Moved so far'=>'Premješteno do sada','%1$s files, %2$s'=>'%1$s datoteka, %2$s','Still on this server'=>'Još uvijek na ovom poslužitelju','%1$s of %2$s attachments'=>'%1$s od %2$s privitaka','Served from'=>'Posluženo iz','this server'=>'ovaj poslužitelj','Connect this site'=>'Povežite ovu web-lokaciju','Open your Zinn Digital® dashboard, go to Storage → Media offload, and press “Pair a site”. Paste the code below.'=>'Otvorite svoju nadzornu ploču Zinn Digital®, idite na Pohrana → Izmještanje medija i pritisnite „Uparite web-mjesto”. Zalijepite kôd u nastavku.','Pairing code'=>'Kod za uparivanje','Disconnect this site'=>'Odspoji ovu stranicu','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'Nova prenesena datoteka ostat će na ovom poslužitelju. Već premješteni medijski sadržaji nastavljaju raditi — njihova adresa se ne mijenja.','You do not have permission to manage this site.'=>'Nemate dopuštenje za upravljanje ovom stranicom.','Paste the pairing code from your Zinn Digital® dashboard.'=>'Zalijepite kod za uparivanje s vaše nadzorne ploče za Zinn Digital®.','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'Povezano. Novi prijenosi od sada će se pohranjivati na Zinn Digital®, a vaši postojeći mediji premjestit će se u pozadini.','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'Prekinuta veza. Mediji koji su već premješteni nastavljaju raditi; novi prijenosi ostaju na ovom poslužitelju.','That file could not be read from this server, so nothing was uploaded.'=>'Tu datoteku nije bilo moguće pročitati s ovog poslužitelja, pa ništa nije učitano.','This site could not stream the upload, so nothing was sent.'=>'Ova stranica nije mogla streamati prijenos, pa ništa nije poslano.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'Ova datoteka je %1$s, a PHP ove stranice nema cURL, tako da je najveća veličina koju može prenijeti %2$s.','The upload could not be completed.'=>'Prijenos nije mogao biti dovršen.','Storage refused the upload (HTTP %d).'=>'Pohrana je odbila prijenos (HTTP %d).','Style preset'=>'Prenamješteni stil','A starting point. Anything below overrides it.'=>'Polazna točka. Sve ispod toga ima prednost.','Use my own colours and sizes'=>'Koristi moje vlastite boje i veličine','Leave this off and the preset is used exactly as it is.'=>'Isključite ovo i predložak se koristi točno onakav kakav jest.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.']];